CREATE TABLE `custom_tracks` (
  `id` int(11) NOT NULL,
  `name` varchar(100) NOT NULL COMMENT '地圖名稱',
  `country` varchar(50) NOT NULL COMMENT '國家',
  `city` varchar(50) NOT NULL COMMENT '縣市',
  `start_lat` double NOT NULL COMMENT '起點緯度',
  `start_lng` double NOT NULL COMMENT '起點經度',
