  `mid2_lat` double DEFAULT NULL COMMENT '審查點2緯度',
  `mid2_lng` double DEFAULT NULL COMMENT '審查點2經度',
  `created_at` timestamp NULL DEFAULT current_timestamp() COMMENT '創建時間',
