  `status` enum('pending','approved','rejected') NOT NULL DEFAULT 'pending',
  `reject_reason` varchar(255) DEFAULT NULL COMMENT '駁回原因',
  `approved_at` datetime DEFAULT NULL COMMENT '審核通過時間',
  `path` longtext DEFAULT NULL COMMENT '預生成路線 JSON',
  `delete_at` datetime DEFAULT NULL,
  `is_deleted` tinyint(1) DEFAULT 0
